将方法拆分为更小的职责单一的方法：
```csharp
// 1. 提取iOS设备MDM信息验证
private static KidIosMdmInfo ValidateIosDeviceMdm(int accountId, long cDeviceId, KidDeviceTypeEnum deviceType, string appVersion)
{
    var tempDeviceId = FlashGetKidsKidHelper.GetDeviceIdForAudio(deviceType, appVersion, accountId, cDeviceId);
    var mdmInfo = FlashGetKidsKidHelper.GetIosChildMdmInfoForEmmApi(tempDeviceId);

    if (mdmInfo == null || mdmInfo.Status != 1)
        throw new KidBizException(DeviceNotCheckIn, "kids device not checkIn", DeviceNotCheckIn);

    if (mdmInfo.IsSupervised != 1)
        throw new KidBizException(DeviceNotSupervised, "kids device not supervised", DeviceNotSupervised);

    return mdmInfo;
}

// 2. 在主方法中调用
if (cDevice.DeviceType == KidDeviceTypeEnum.iOSChild.GetHashCode())
{
    mdmInfo = ValidateIosDeviceMdm(accountId, cDeviceId, req.DeviceType, req.AppVersion);
}
```

